/**
 * Static-data mode.
 *
 * When the app is built with VITE_STATIC_DATA=true it reads pre-built JSON
 * files from /static-data (generated by data-pipeline/static_snapshot/
 * build_snapshot.py) instead of calling the FastAPI backend. Metrics that
 * depend on UN Comtrade trade data are not in the snapshot and are disabled
 * in the UI.
 */
import { useQuery } from '@tanstack/react-query'
import type { ChoroplethMetric } from '@/shared/types'

export const IS_STATIC = import.meta.env.VITE_STATIC_DATA === 'true'

export const STATIC_BASE = `${import.meta.env.BASE_URL.replace(/\/$/, '')}/static-data`

// Metrics present in the snapshot. Kept in sync with AVAILABLE_METRICS in
// build_snapshot.py; meta.json is the runtime source of truth.
export const STATIC_METRICS: ChoroplethMetric[] = ['generation', 'per_capita', 'formal_collection', 'prs']

export const FULL_STACK_LABEL = 'needs full stack'

export function isMetricAvailable(metric: ChoroplethMetric): boolean {
  return !IS_STATIC || STATIC_METRICS.includes(metric)
}

export type SnapshotSource = { name: string; url: string; used_for: string }

export type SnapshotMeta = {
  snapshot_date: string
  year_range: [number, number]
  available_metrics: ChoroplethMetric[]
  unavailable_metrics: ChoroplethMetric[]
  unavailable_reason: string
  counts: Record<string, number>
  notes: string[]
  sources: SnapshotSource[]
  excluded: { iso3: string; years: number[]; reason: string }[]
}

export async function fetchStatic<T>(path: string): Promise<T> {
  const res = await fetch(`${STATIC_BASE}/${path}`)
  if (!res.ok) {
    throw new StaticDataError(res.status, `Static snapshot has no ${path}`)
  }
  return res.json() as Promise<T>
}

export class StaticDataError extends Error {
  constructor(
    public readonly status: number,
    message: string,
  ) {
    super(message)
    this.name = 'StaticDataError'
  }
}

export function useSnapshotMeta() {
  return useQuery({
    queryKey: ['static-meta'],
    queryFn: () => fetchStatic<SnapshotMeta>('meta.json'),
    enabled: IS_STATIC,
    staleTime: Infinity,
  })
}
